    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Combat.html&quot; title=&quot;Dons de combat&quot;&gt;Dons de combat&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Cr&#233;ation-Dobjets.html&quot; title=&quot;Dons de cr&#233;ation d&amp;#39;objets&quot;&gt;Dons de cr&#233;ation d&#39;objets&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Critique.html&quot; title=&quot;Dons de critique&quot;&gt;Dons de critique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;cole.html&quot; title=&quot;Dons d&amp;#39;&#233;cole&quot;&gt;Dons d&#39;&#233;cole&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;quipe.html&quot; title=&quot;Dons d&amp;#39;&#233;quipe&quot;&gt;Dons d&#39;&#233;quipe&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darme.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;arme&quot;&gt;Dons de ma&#238;trise d&#39;arme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darmure.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;armure&quot;&gt;d&#39;armure&lt;/a&gt;,&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-De-Bouclier.html&quot; title=&quot;Dons de ma&#238;trise de bouclier&quot;&gt;de bouclier&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Dobjets.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;objet&quot;&gt;d&#39;objet&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Mal&#233;fice-Sanglant.html&quot; title=&quot;Dons de mal&#233;fice sanglant&quot;&gt;Dons de mal&#233;fice sanglant&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-M&#233;tamagie.html&quot; title=&quot;Dons de m&#233;tamagie&quot;&gt;Dons de m&#233;tamagie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Regard.html&quot; title=&quot;dons de regard&quot;&gt;Dons de regard&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-R&#233;ussite.html&quot; title=&quot;Dons de r&#233;ussite&quot;&gt;Dons de r&#233;ussite&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Spectacle.html&quot; title=&quot;Dons de spectacle&quot;&gt;Dons de spectacle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dalignement.html&quot; title=&quot;Dons d&amp;#39;alignement&quot;&gt;Dons d&#39;alignement (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dhistoire.html&quot; title=&quot;Dons d&amp;#39;histoire&quot;&gt;Dons d&#39;histoire (GC)&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-&#201;sot&#233;riques.html&quot; title=&quot;Dons &#233;sot&#233;riques&quot;&gt;Dons &#233;sot&#233;riques (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;R&#232;gles g&#233;n&#233;rales&lt;/li&gt;
    &lt;ul&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DESCRIPTION&quot; title=&quot;Les dons&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#TYPES&quot; title=&quot;Les dons&quot;&gt;types de dons&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;script&gt;
$(function () {
  $(&quot;tr.donpr&#233;requis0, tr.donpr&#233;requis1, tr.donpr&#233;requis2&quot;).hide();
  $(&quot;tr.donprincipal&quot;).bind(&quot;click&quot;, togglePrereq);
  $(&quot;tr.donpr&#233;requis0&quot;).bind(&quot;click&quot;, togglePrereq0);
  $(&quot;tr.donpr&#233;requis1&quot;).bind(&quot;click&quot;, togglePrereq1);
  $(&quot;tr.donprincipal&quot;).each(addPrereqIconIfNeeded);
  $(&quot;tr.donpr&#233;requis0&quot;).each(addPrereqIconIfNeeded0);
  $(&quot;tr.donpr&#233;requis1&quot;).each(addPrereqIconIfNeeded1);
  $(&quot;tr.donpr&#233;requis2&quot;).each(addPrereqIconIfNeeded2);
});
function togglePrereq() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis0&quot;) || node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq0() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq1() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      node = node.next();
    }
}
function addPrereqIconIfNeeded() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded0() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded1() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis2&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
function addPrereqIconIfNeeded2() {
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;) || next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
&lt;/script&gt;&lt;i&gt;Les dons marqu&#233;s d&#39;un ast&#233;risque (*) sont des dons de combat.&lt;/i&gt;
&lt;table CLASS=&quot;tablo centre toutgauche&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Tableau r&#233;capitulatif des dons g&#233;n&#233;raux&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;42%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#192;-Terre-&#192;-Cheval.html&quot; title=&quot;&#192; terre &#224; cheval&quot;&gt;&#192; terre &#224; cheval&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-(Guerrier).html&quot; title=&quot;Dragon&quot;&gt;bond du lancier&lt;/a&gt;, 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, 11 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage remonte en selle par une action rapide s&#39;il r&#233;ussit un test d&#39;Acrobaties&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Abondance-De-R&#233;v&#233;lations.html&quot; title=&quot;Abondance de r&#233;v&#233;lations&quot;&gt;Abondance de r&#233;v&#233;lations&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Oracle.html#MYSTERE&quot; title=&quot;L&amp;#39;oracle&quot;&gt;myst&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Utiliser une unique r&#233;v&#233;lation plus de fois par jour.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-Rageuse.html&quot; title=&quot;Absorption rageuse&quot;&gt;Absorption rageuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; lancer des sorts de &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;sanguin&lt;/a&gt; de 2e niveau, capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html#RAGESANGUINE&quot; title=&quot;Le sanguin&quot;&gt;rage sanguine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage absorbe l&#39;&#233;nergie magique des sorts agressifs pour alimenter sa rage sanguine&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acolyte-De-La-Nature.html&quot; title=&quot;Acolyte de la Nature&quot;&gt;Acolyte de la Nature&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CCMI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Suivant de la &lt;a class=&quot;pagelink&quot; href=&quot;../Golarion/Foi-Verte.html&quot; title=&quot;La Foi Verte&quot;&gt;voie de la nature&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les sorts sont plus efficaces sur les plantes&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobate-Des-Corniches.html&quot; title=&quot;Acrobate des corniches&quot;&gt;Acrobate des corniches&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;Dex&quot;&gt;Dex&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;nain&lt;/a&gt;, trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html#Traits_raciaux_alternatifs_7&quot; title=&quot;Les nains&quot;&gt;montagnard&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html#Traits_raciaux_standards_6&quot; title=&quot;Les nains&quot;&gt;stabilit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;D&#233;placement plus rapide sur les espaces restreints&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobate-Rus&#233;.html&quot; title=&quot;Acrobate rus&#233;&quot;&gt;Acrobate rus&#233;&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Souplesse-Du-Serpent.html&quot; title=&quot;Souplesse du serpent&quot;&gt;Souplesse du serpent&lt;/a&gt;, 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage gagne un bonus aux jets d&#39;attaque au corps &#224; corps quand il utilise Acrobaties pour &#233;viter des attaques d&#39;opportunit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Action-F&#233;roce.html&quot; title=&quot;Action f&#233;roce&quot;&gt;Action f&#233;roce&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html#Traits_raciaux_standards_6&quot; title=&quot;Les orques&quot;&gt;f&#233;rocit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;orque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Emp&#234;che d&#39;&#234;tre chancelant avec des points de vie n&#233;gatifs aux prix de les perdre plus vite&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Activation-Myst&#233;rieuse.html&quot; title=&quot;Activation myst&#233;rieuse&quot;&gt;Activation myst&#233;rieuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;12 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d&#39;objets magiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Augmente le NLS de l&#39;objet utilis&#233; en d&#233;passant le test d&#39;UOM&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adaptation-Aquatique.html&quot; title=&quot;Adaptation aquatique&quot;&gt;Adaptation aquatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Retenir-Son-Souffle-(Capacit&#233;).html&quot; title=&quot;Retenir son souffle (Ext)&quot;&gt;retenir son souffle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Respire aussi bien l&#39;eau que l&#39;air&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-De-La-Discipline.html&quot; title=&quot;Adepte de la discipline&quot;&gt;Adepte de la discipline&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html#DISCIPLINEPSYCHIQUE&quot; title=&quot;Le psychiste&quot;&gt;discipline psychique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+1 aux tests de niveau de lanceur de sorts, de concentration et aux jets de sauvegarde pour les sorts de discipline&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-De-La-Matraque.html&quot; title=&quot;Adepte de la matraque&quot;&gt;Adepte de la matraque&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Attaquesournoise.html&quot; title=&quot;attaque sournoise&quot;&gt;Attaque sournoise&lt;/a&gt; +1d6&lt;/td&gt;&lt;td&gt;Bonus de d&#233;g&#226;ts aux attaques non l&#233;tales&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ma