itesse de base du personnage quand sa taille est augment&#233;e&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pas-L&#233;ger.html&quot; title=&quot;Pas l&#233;ger&quot;&gt;Pas l&#233;ger&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Acrobatique.html&quot; title=&quot;D&#233;placement acrobatique&quot;&gt;D&#233;placement acrobatique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Aisance.html&quot; title=&quot;Aisance&quot;&gt;Aisance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfe&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Se d&#233;placer de sa Vitesse de d&#233;placement normale sur un terrain difficile&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Passer-Pour-Un-Humain.html&quot; title=&quot;Passer pour un humain&quot;&gt;Passer pour un humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;halfelin&lt;/a&gt; (voir texte)&lt;/td&gt;&lt;td&gt;+10 aux tests de D&#233;guisement pour ressembler &#224; un humain&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Patrouille-En-Combat.html&quot; title=&quot;Patrouille en combat&quot;&gt;Patrouille en combat&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quo